  news2:{title:'NEWS2',short:'NEWS2',description:'Akut hastalıkta fizyolojik kötüleşmeyi yedi parametreyle değerlendirir.',sections:[['Solunum',[num('rr','Solunum sayısı','/dk',3,80,1),choice('spo2Scale','SpO₂ ölçeği',[['1','Ölçek 1 — standart'],['2','Ölçek 2 — doğrulanmış hiperkapnik solunum yetmezliği']]),num('sat','SpO₂','%',40,100,1),yes('oxygen','Ek oksijen alıyor')]],['Dolaşım ve diğer',[num('sbp','Sistolik kan basıncı','mmHg',40,300,1),num('hr','Kalp hızı','/dk',20,250,1),num('temp','Sıcaklık','°C',25,45,.1),choice('conscious','Bilinç',[['0','Alert'],['3','Yeni konfüzyon / V-P-U']])]]],calc:v=>{const component=[];component.push(v.rr<=8?3:v.rr<=11?1:v.rr<=20?0:v.rr<=24?2:3);let os=0;if(v.spo2Scale==='1')os=v.sat<=91?3:v.sat<=93?2:v.sat<=95?1:0;else if(v.sat<=83)os=3;else if(v.sat<=85)os=2;else if(v.sat<=87)os=1;else if(v.sat<=92)os=0;else if(!v.oxygen)os=0;else os=v.sat<=94?1:v.sat<=96?2:3;component.push(os);component.push(v.oxygen?2:0);component.push(v.sbp<=90?3:v.sbp<=100?2:v.sbp<=110?1:v.sbp<=219?0:3);component.push(v.hr<=40?3:v.hr<=50?1:v.hr<=90?0:v.hr<=110?1:v.hr<=130?2:3);component.push(v.temp<=35?3:v.temp<=36?1:v.temp<=38?0:v.temp<=39?1:2);component.push(+v.conscious);const s=component.reduce((a,b)=>a+b,0),single3=component.some(x=>x===3);return s>=7?res(s,'Yüksek klinik risk','Acil/erken yanıt, sürekli monitorizasyon ve üst düzey klinik değerlendirme gerekir.','high'):s>=5?res(s,'Orta klinik risk','Acil klinik değerlendirme ve sık monitorizasyon gerekir.','mid'):single3?res(s,'Tek parametrede ciddi sapma','Toplam düşük olsa da bir parametre 3 puan; klinik değerlendirme ve daha sık izlem gerekir.','mid'):res(s,'Düşük klinik risk','Rutin NEWS2 izlem sıklığı ve klinik değerlendirme uygundur.','low','NEWS2 tanı koymaz; klinik kötüleşmede skordan bağımsız acil değerlendirme yapılır.')}},
