  chadsvasc:{title:'CHA₂DS₂-VASc',short:'CHA₂DS₂-VASc',description:'Nonvalvüler AF’de tromboembolik inme riskini değerlendirir.',sections:[['Risk faktörleri',[yes('chf','Kalp yetersizliği / LV sistolik disfonksiyon'),yes('ht','Hipertansiyon'),choice('age','Yaş',[['0','<65'],['1','65–74'],['2','≥75']]),yes('dm','Diyabetes mellitus'),yes('stroke','İnme / TİA / sistemik emboli öyküsü','2 puan',2),yes('vascular','Vasküler hastalık','MI, periferik arter hastalığı veya aort plağı'),yes('female','Kadın cinsiyet')]]],calc:v=>{const s=(v.chf?1:0)+(v.ht?1:0)+(+v.age)+(v.dm?1:0)+(v.stroke?2:0)+(v.vascular?1:0)+(v.female?1:0);const sexOnly=v.female&&s===1;return (s===0||sexOnly)?res(s,'Düşük tromboemboli riski','Kadın cinsiyet tek başına risk değiştiricidir; ek risk faktörü yoksa düşük risk kabul edilir.','low'):res(s,s>=2?'Artmış tromboemboli riski':'Ara risk','Antikoagülasyon kararı güncel AF kılavuzu, cinsiyet ve hasta tercihleriyle birlikte verilmelidir.',s>=2?'high':'mid','Mekanik kapak veya orta-ağır mitral darlığında bu skor kullanılmaz.')}},
